mapper.select:
        select
        mn.*
        from Sys_Portal_Design_Template mn
        
            
                and mn.Pdt_Type=#{params.pdtType}
            
            
                and mn.Pdt_State=#{params.pdtState}
            
            
                and mn.T_Id=#{params.tId}
            
            
                and INSTR(mn.Pdt_Create_Nmae,#{params.pdtCreateNmae})
            
            
                and INSTR(mn.Pdt_Code,#{params.pdtCode})
            

            
                and INSTR(mn.Pdt_Name,#{params.pdtName})
            
        
        
            
                order by mn.${params.sortFiled} ${params.sortType}
            
            
                order by ${params.sortSideFiled} ${params.sortType}
            
            
                order by mn.Pdt_Create_Time desc
